<#
.SYNOPSIS
    Lint (or auto-fix) PowerShell files against AP Console house style.
.DESCRIPTION
    Enforces the rules in apconsole-operator/references/powershell-style.md:
      ? Tight inline braces ? no space after `@{` / `{`, no space before `}`
        (only flagged on single-line blocks; multi-line bodies are untouched)
      ? Verbose cmdlets ? succinct aliases (`ForEach-Object` ? `%`, etc.)
      ? `-not $x` ? `!$x`
      ? `-ErrorAction SilentlyContinue` ? `-ea 0`

    Uses PowerShell's AST parser, so it never mangles string literals, comments,
    or here-strings. Prettier-inspired UX: no flags = report; `-Fix` = rewrite.

.PARAMETER Path
    Files, globs, or directories. Directories are scanned recursively for
    *.ps1 and *.psm1. Defaults to *.ps1 / *.psm1 in the current directory.

.PARAMETER Fix
    Apply auto-fixes in place. All rules this linter emits are safe to auto-fix
    (they're pure substitutions that preserve semantics). Alias: `-AutoFix`.

.PARAMETER Quiet
    Suppress per-issue output; only print the final summary.

.EXAMPLE
    APConsole-Linter.ps1 Modules.ps1
    APConsole-Linter.ps1 .\AP-Components
    APConsole-Linter.ps1 -Fix .\GIT-Manager.ps1
#>
using namespace System.Management.Automation
using namespace System.Management.Automation.Language
using namespace System.Collections.Generic

# Two parameter sets:
#   Lint (default) ? default read-only analysis path. Accepts -Path, -Quiet.
#   Fix            ? activated by -Fix. Unlocks -AllOptional, which also
#                    applies rules tagged Optional (e.g. native-ternary rewrite).
# Passing -AllOptional without -Fix is rejected by PowerShell parameter binding.
# NOTE: avoid apostrophes, parens, or quotes in the param() doc-comments below.
# AP-Compile.ps1 scans param(...) char-by-char and does not skip comment bodies,
# so an unbalanced apostrophe inside a comment breaks its string-tracker and the
# compile block lands at end-of-file instead of after param(...).
[CmdletBinding(DefaultParameterSetName = 'Lint')]
param(
    [Parameter(Position = 0, ValueFromRemainingArguments = $true, ParameterSetName = 'Lint')]
    [Parameter(Position = 0, ValueFromRemainingArguments = $true, ParameterSetName = 'Fix')]
    [string[]]$Path,

    [Parameter(ParameterSetName = 'Lint')]
    [Parameter(ParameterSetName = 'Fix')]
    [switch]$Quiet,

    [Parameter(ParameterSetName = 'Fix', Mandatory)]
    [Alias("AutoFix")][switch]$Fix,

    [Parameter(ParameterSetName = 'Fix')]
    [Alias("All")][switch]$AllOptional
)
# =======================================START=OF=COMPILER================================================================|
#    The Following Code was added by AP-Compiler 1.6 (APC: 1.3) To Make this program independent of AP-Core Engine
#    GitHub: https://github.com/avdaredevil/AP-Compiler
# ========================================================================================================================|
$Script:PSHell=$(if($PSHell){$PSHell}elseif($PSScriptRoot){$PSScriptRoot}else{"."});
if($AP_CONSOLE.mode -ne 'main' -or $AP_CONSOLE.customFlags.runAsCompiled) {
    $Script:AP_CONSOLE = [PsCustomObject]@{version=[version]'1.3'; mode = 'shim'; customFlags = @{}}
    function B64 {param([Parameter(ValueFromPipeline=$true)][String]$Text, [ValidateSet("UTF8","Unicode")][String]$Encoding = "UTF8")     [System.Text.Encoding]::$Encoding.GetString([System.Convert]::FromBase64String($Text))}
    # This syntax is to prevent AV's from misclassifying this as anything but innocuous
    & (Get-Alias iex) (B64 "")
} elseif($AP_CONSOLE.warnOnCompileRun) {& $AP_CONSOLE.warnOnCompileRun}
# ========================================END=OF=COMPILER=================================================================|

if (!$Path) {$Path = @("*.ps1", "*.psm1")}

# On Linux pwsh, `sort`/`ls`/etc. resolve to /usr/bin/* instead of the cmdlets.
# `Load-LinuxAliases` (AP Console) restores them ? no-op on Windows.
Load-LinuxAliases

# Verbose ? alias map. Only list verbose forms the style guide explicitly calls out.
# Deliberately not listing every built-in alias (e.g. `Get-ChildItem` ? `gci`) ?
# those aren't mandated and would produce noisy diffs in existing code.
$script:aliasMap = [ordered]@{
    'ForEach-Object'    = '%'
    'Where-Object'      = '?'
    'Select-Object'     = 'select'
    'Invoke-Expression' = 'iex'
    'Set-Alias'         = 'sal'
}

function New-Issue {
    param(
        $File, $Line, $Col, $Rule, $Message, $Offset, $Length, $Replacement,
        [switch]$Optional, [switch]$WarnOnly
    )
    [PSCustomObject]@{
        File        = $File
        Line        = $Line
        Col         = $Col
        Rule        = $Rule
        Message     = $Message
        Offset      = $Offset
        Length      = $Length
        Replacement = $Replacement
        Optional    = [bool]$Optional
        WarnOnly    = [bool]$WarnOnly
    }
}

function Find-Issues {
    param([string]$FilePath)
    $text = [System.IO.File]::ReadAllText($FilePath)
    if (!$text) {return @()}

    $tokens = $null; $parseErrors = $null
    $ast = [Parser]::ParseInput(
        $text, [ref]$tokens, [ref]$parseErrors
    )
    if (!$ast) {return @()}

    $issues = [List[object]]::new()

    # --- Rule: tight hashtables (inline only) -------------------------------
    # Multi-line hashtables (4+ keys on separate lines) are idiomatic and intentional;
    # the rule only bites on single-line forms like `@{ key = val }`.
    $hashtables = $ast.FindAll(
        {$args[0] -is [HashtableAst]}, $true
    )
    foreach ($h in $hashtables) {
        if ($h.Extent.StartLineNumber -ne $h.Extent.EndLineNumber) {continue}
        $t = $h.Extent.Text
        if ($t -match '^@\{(\s+)') {
            $spLen = $Matches[1].Length
            $issues.Add((New-Issue $FilePath `
                $h.Extent.StartLineNumber ($h.Extent.StartColumnNumber + 2) `
                'tight-hashtable' 'Remove space after `@{` in inline hashtable' `
                ($h.Extent.StartOffset + 2) $spLen ''))
        }
        if ($t -match '(\s+)\}$') {
            $spLen = $Matches[1].Length
            $issues.Add((New-Issue $FilePath `
                $h.Extent.EndLineNumber ($h.Extent.EndColumnNumber - 1 - $spLen) `
                'tight-hashtable' 'Remove space before `}` in inline hashtable' `
                ($h.Extent.EndOffset - 1 - $spLen) $spLen ''))
        }
    }

    # --- Rule: tight scriptblocks (inline only) -----------------------------
    # Covers `{ $_.x }`, `{ return }`, `if (y) { doit }`, etc. Multi-line bodies
    # (where `{` ends the line and the closing `}` is on its own line) are skipped.
    $blocks = $ast.FindAll({
        $a = $args[0]
        ($a -is [ScriptBlockExpressionAst]) -or
        ($a -is [StatementBlockAst])
    }, $true)
    foreach ($b in $blocks) {
        if ($b.Extent.StartLineNumber -ne $b.Extent.EndLineNumber) {continue}
        $t = $b.Extent.Text
        if (!$t.StartsWith('{') -or !$t.EndsWith('}')) {continue}
        # `{ ` but NOT `{}` (skip empty blocks ? no violation to flag)
        if ($t -match '^\{(\s+)[^\s}]') {
            $spLen = $Matches[1].Length
            $issues.Add((New-Issue $FilePath `
                $b.Extent.StartLineNumber ($b.Extent.StartColumnNumber + 1) `
                'tight-scriptblock' 'Remove space after `{` in inline scriptblock' `
                ($b.Extent.StartOffset + 1) $spLen ''))
        }
        if ($t -match '[^\s{](\s+)\}$') {
            $spLen = $Matches[1].Length
            $issues.Add((New-Issue $FilePath `
                $b.Extent.EndLineNumber ($b.Extent.EndColumnNumber - 1 - $spLen) `
                'tight-scriptblock' 'Remove space before `}` in inline scriptblock' `
                ($b.Extent.EndOffset - 1 - $spLen) $spLen ''))
        }
    }

    # --- Rule: cmdlet aliases -----------------------------------------------
    $commands = $ast.FindAll(
        {$args[0] -is [CommandAst]}, $true
    )
    foreach ($c in $commands) {
        if (!$c.CommandElements) {continue}
        $nameEl = $c.CommandElements[0]
        if ($nameEl -isnot [StringConstantExpressionAst]) {continue}
        $name = $nameEl.Value
        if (!$script:aliasMap.Contains($name)) {continue}
        $alias = $script:aliasMap[$name]
        $ruleId = 'alias-' + ($name.ToLower() -replace '-','')
        $issues.Add((New-Issue $FilePath `
            $nameEl.Extent.StartLineNumber $nameEl.Extent.StartColumnNumber `
            $ruleId "Use ``$alias`` instead of ``$name``" `
            $nameEl.Extent.StartOffset ($nameEl.Extent.EndOffset - $nameEl.Extent.StartOffset) $alias))
    }

    # --- Rule: `-not` ? `!` -------------------------------------------------
    $unary = $ast.FindAll(
        {$args[0] -is [UnaryExpressionAst]}, $true
    )
    foreach ($u in $unary) {
        if ($u.TokenKind -ne [TokenKind]::Not) {continue}
        if (!$u.Child) {continue}
        # Replace `-not ` (including the space, which `Child.Extent.StartOffset` skips past)
        # with `!`. If the source was `-not$x` (no space), the length is 4 and we still
        # produce `!$x`.
        $replaceLen = $u.Child.Extent.StartOffset - $u.Extent.StartOffset
        $issues.Add((New-Issue $FilePath `
            $u.Extent.StartLineNumber $u.Extent.StartColumnNumber `
            'alias-not' 'Use `!$x` instead of `-not $x`' `
            $u.Extent.StartOffset $replaceLen '!'))
    }

    # --- Rule: `-ErrorAction SilentlyContinue` ? `-ea 0` --------------------
    foreach ($c in $commands) {
        for ($i = 0; $i -lt $c.CommandElements.Count - 1; $i++) {
            $el = $c.CommandElements[$i]
            $next = $c.CommandElements[$i + 1]
            if ($el -isnot [CommandParameterAst]) {continue}
            if ($el.ParameterName -ne 'ErrorAction') {continue}
            if ($next -isnot [StringConstantExpressionAst]) {continue}
            if ($next.Value -ne 'SilentlyContinue') {continue}
            $startOff = $el.Extent.StartOffset
            $endOff = $next.Extent.EndOffset
            $issues.Add((New-Issue $FilePath `
                $el.Extent.StartLineNumber $el.Extent.StartColumnNumber `
                'alias-ea' 'Use `-ea 0` instead of `-ErrorAction SilentlyContinue`' `
                $startOff ($endOff - $startOff) '-ea 0'))
        }
    }

    # --- Rule: $null comparison order (array-safety) -----------------------
    # `$x -eq $null` evaluates to $null (not $false) when `$x` is an array,
    # because -eq broadcasts across array elements. `$null -eq $x` uses the
    # scalar comparison path and is always boolean. Flag any comparison with
    # `$null` on the right-hand side of -eq / -ne (both case variants).
    $binaries = $ast.FindAll(
        {$args[0] -is [BinaryExpressionAst]}, $true
    )
    foreach ($be in $binaries) {
        $op = "$($be.Operator)"
        if ($op -notin 'Ieq','Ine','Ceq','Cne') {continue}
        $r = $be.Right
        if ($r -isnot [VariableExpressionAst]) {continue}
        if ($r.VariablePath.UserPath -ne 'null') {continue}
        $l = $be.Left
        # Skip the `$null -eq $null` edge case (both sides are $null).
        if (($l -is [VariableExpressionAst]) -and
            $l.VariablePath.UserPath -eq 'null') {continue}
        # Skip multi-line LHS -- swapping could produce awkward layout.
        if ($l.Extent.StartLineNumber -ne $l.Extent.EndLineNumber) {continue}
        # Preserve the exact operator whitespace (`$x  -eq   $null` stays spaced).
        $between = $text.Substring($l.Extent.EndOffset, $r.Extent.StartOffset - $l.Extent.EndOffset)
        $replacement = '$null' + $between + $l.Extent.Text
        $issues.Add((New-Issue $FilePath `
            $be.Extent.StartLineNumber $be.Extent.StartColumnNumber `
            'null-compare-order' 'Put `$null` on the left of `-eq`/`-ne` for array-safe comparison' `
            $be.Extent.StartOffset ($be.Extent.EndOffset - $be.Extent.StartOffset) $replacement))
    }

    # --- Rule: redundant $true / $false comparison --------------------------
    # `$x -eq $true`  -> `$x`        `$x -ne $true`  -> `!$x`
    # `$x -ne $false` -> `$x`        `$x -eq $false` -> `!$x`
    # LHS kinds safe to prepend `!` verbatim: variable, member, method-invoke,
    # index, paren. Anything else (e.g. a bare command expression) gets wrapped
    # as `!(<lhs>)` to preserve precedence.
    $simpleLhsKinds = 'VariableExpressionAst','MemberExpressionAst',
                      'InvokeMemberExpressionAst','IndexExpressionAst','ParenExpressionAst'
    foreach ($be in $binaries) {
        $op = "$($be.Operator)"
        if ($op -notin 'Ieq','Ine','Ceq','Cne') {continue}
        $r = $be.Right
        if ($r -isnot [VariableExpressionAst]) {continue}
        $rPath = $r.VariablePath.UserPath
        if ($rPath -notin 'true','false') {continue}
        $l = $be.Left
        if ($l.Extent.StartLineNumber -ne $l.Extent.EndLineNumber) {continue}
        # XOR: negate iff exactly one of {-ne, $false} is true.
        $isNe = $op -in 'Ine','Cne'
        $isFalse = $rPath -eq 'false'
        $negate = $isNe -xor $isFalse
        $lText = $l.Extent.Text
        $isSimple = $l.GetType().Name -in $simpleLhsKinds
        $replacement = if ($negate) {
            if ($isSimple) {"!$lText"} else {"!($lText)"}
        } else {$lText}
        $issues.Add((New-Issue $FilePath `
            $be.Extent.StartLineNumber $be.Extent.StartColumnNumber `
            'redundant-bool-compare' "Use ``$replacement`` instead of ``$($be.Extent.Text)``" `
            $be.Extent.StartOffset ($be.Extent.EndOffset - $be.Extent.StartOffset) $replacement))
    }

    # --- Rule: New-Object PSObject -> [PSCustomObject]@{...} ----------------
    # `New-Object PSObject -Property @{...}` and its `PSCustomObject` variant
    # are the old PS2 idiom. The type-literal cast is faster (no cmdlet overhead)
    # and reads better. Accepts both positional `New-Object PSObject` and the
    # named `-TypeName PSObject` form.
    foreach ($c in $commands) {
        if (!$c.CommandElements -or $c.CommandElements.Count -lt 2) {continue}
        $nameEl = $c.CommandElements[0]
        if ($nameEl -isnot [StringConstantExpressionAst]) {continue}
        if ($nameEl.Value -ne 'New-Object') {continue}
        $typeName = $null; $propHash = $null; $seenPositional = $false
        for ($k = 1; $k -lt $c.CommandElements.Count; $k++) {
            $el = $c.CommandElements[$k]
            if ($el -is [CommandParameterAst]) {
                $pname = $el.ParameterName
                $next = if ($k + 1 -lt $c.CommandElements.Count) {$c.CommandElements[$k + 1]} else {$null}
                if ($pname -in 'TypeName','t' -and $next -is [StringConstantExpressionAst]) {
                    $typeName = $next.Value; $k++
                } elseif ($pname -in 'Property','p' -and $next -is [HashtableAst]) {
                    $propHash = $next; $k++
                }
                continue
            }
            # Positional: 1st non-parameter is the type name.
            if (!$seenPositional -and $el -is [StringConstantExpressionAst]) {$typeName = $el.Value}
            $seenPositional = $true
        }
        if ($typeName -notin 'PSObject','PSCustomObject','System.Management.Automation.PSObject') {continue}
        if (!$propHash) {continue}
        $replacement = "[PSCustomObject]$($propHash.Extent.Text)"
        $issues.Add((New-Issue $FilePath `
            $c.Extent.StartLineNumber $c.Extent.StartColumnNumber `
            'new-object-pscustomobject' 'Use `[PSCustomObject]@{...}` instead of `New-Object PSObject -Property @{...}`' `
            $c.Extent.StartOffset ($c.Extent.EndOffset - $c.Extent.StartOffset) $replacement))
    }

    # --- Rule: legacy Write-AP prefix-flag syntax -> Write-APL --------------
    # Write-AP takes per-arg flag prefixes (`x` = no newline, `n`/`s` = no sign
    # bracket) that Write-APL auto-applies internally for you. Any hand-crafted
    # Write-AP call matching the canonical PrefixCode pattern (first `x`, middle
    # `nx`, last `n`) is semantically equivalent to a Write-APL call with the
    # flags stripped. This rule flags that pattern and auto-rewrites it.
    #
    # The flag-on-first-`n` case maps to `-NoSign` (alias `-NS`) on Write-APL,
    # and the flag-on-last-`x` case maps to `-NoNewLine` (`-NNL`). These are
    # the only first/last flag variations that still produce a valid single-
    # line chain (and Write-APL's only supported customisation points).
    $wapFullRgx = '^((?<NNL>x)|(?<NS>ns?)){0,2}(?<t>\>*)(?<s>[\+\-\!\*\#\@_])(?<w>.*)$'
    $wapStripRgx = '^(n?x?n?)(\>*[\+\-\!\*\#\@_])'
    $parseWapPrefix = {
        param([string]$Literal)
        if ($Literal -notmatch $wapFullRgx) {return $null}
        $flags = @()
        if ($Matches.NNL) {$flags += 'x'}
        if ($Matches.NS)  {$flags += 'n'}
        $flagLen = $Matches[0].Length - $Matches.t.Length - 1 - $Matches.w.Length
        @{FlagLen = $flagLen; Flags = $flags; Indent = $Matches.t; Sign = $Matches.s; Body = $Matches.w}
    }
    # For expandable strings, the flag prefix must live entirely before any
    # $var / $(...) interpolation. Return the literal head text.
    $getLiteralHead = {
        param($Ast)
        if ($Ast -is [ExpandableStringExpressionAst] -and $Ast.NestedExpressions) {
            $firstOff = ($Ast.NestedExpressions | sort {$_.Extent.StartOffset})[0].Extent.StartOffset
            $cut = $firstOff - $Ast.Extent.StartOffset - 1
            return $Ast.Value.Substring(0, [Math]::Max(0, $cut))
        }
        return $Ast.Value
    }

    # Helper: PowerShell parses `Write-AP "a","b","c"` with the comma-joined args
    # as a SINGLE ArrayLiteralAst (not three positional elements). Flatten those
    # out so position-based rules can see the individual string constants.
    $flattenArgs = {
        param($Elements)
        $out = [List[object]]::new()
        foreach ($e in $Elements) {
            if ($e -is [ArrayLiteralAst]) {
                foreach ($inner in $e.Elements) {$out.Add($inner)}
            } else {$out.Add($e)}
        }
        return $out
    }

    foreach ($c in $commands) {
        if (!$c.CommandElements -or $c.CommandElements[0].Value -ne 'Write-AP') {continue}
        $posArgs = [List[object]]::new()
        $hasNS = $false; $hasNNL = $false; $bail = $false
        # Walk CommandElements, splitting named params from positional, and
        # flattening any ArrayLiteralAst positional arg into its elements.
        for ($k = 1; $k -lt $c.CommandElements.Count; $k++) {
            $el = $c.CommandElements[$k]
            if ($el -is [CommandParameterAst]) {
                switch ($el.ParameterName) {
                    {$_ -in 'NoSign','NS'}           {$hasNS = $true;  break}
                    {$_ -in 'NoNewLine','NNL','NL'}  {$hasNNL = $true; break}
                    default                          {$bail = $true}
                }
                if ($bail) {break}
                continue
            }
            foreach ($inner in (& $flattenArgs @($el))) {
                $isStr = ($inner -is [StringConstantExpressionAst]) -or
                         ($inner -is [ExpandableStringExpressionAst])
                if (!$isStr -or $inner.Extent.Text.StartsWith('@')) {$bail = $true; break}
                $posArgs.Add($inner)
            }
            if ($bail) {break}
        }
        if ($bail -or $posArgs.Count -lt 2) {continue}

        $parsed = @(); $ok = $true
        foreach ($a in $posArgs) {
            $lit = & $getLiteralHead $a
            if ($lit -match "`n") {$ok = $false; break}
            $p = & $parseWapPrefix $lit
            if (!$p) {$ok = $false; break}
            # Flag prefix must fit inside the literal head (not extend into interpolation).
            if ($p.FlagLen + $p.Indent.Length + 1 -gt $lit.Length) {$ok = $false; break}
            $parsed += $p
        }
        if (!$ok) {continue}

        # Position-aware flag validation.
        if ('x' -notin $parsed[0].Flags) {continue}
        if ('n' -notin $parsed[-1].Flags) {continue}
        for ($i = 1; $i -lt $parsed.Count - 1; $i++) {
            $fs = ($parsed[$i].Flags | sort) -join ''
            if ($fs -ne 'nx') {$ok = $false; break}
        }
        if (!$ok) {continue}

        $needNS  = $hasNS  -or ('n' -in $parsed[0].Flags)
        $needNNL = $hasNNL -or ('x' -in $parsed[-1].Flags)

        # Emit the cmdlet-rename issue (with optional switch injection).
        $nameEl = $c.CommandElements[0]
        $newName = "Write-APL"
        if ($needNS)  {$newName += " -NS"}
        if ($needNNL) {$newName += " -NNL"}
        $issues.Add((New-Issue $FilePath `
            $nameEl.Extent.StartLineNumber $nameEl.Extent.StartColumnNumber `
            'write-ap-to-apl' 'Use `Write-APL` (legacy `Write-AP` flag prefixes are auto-applied by `Write-APL`)' `
            $nameEl.Extent.StartOffset ($nameEl.Extent.EndOffset - $nameEl.Extent.StartOffset) $newName))

        # Emit per-arg flag-strip issues (plus `_`-drop when safe).
        for ($i = 0; $i -lt $posArgs.Count; $i++) {
            $a = $posArgs[$i]; $p = $parsed[$i]
            $openQuote = $a.Extent.StartOffset + 1
            $replaceLen = $p.FlagLen
            $replacement = ''
            if ($p.Sign -eq '_' -and $p.Body.Length -gt 0 -and $p.Body[0] -notmatch '[\+\-\!\*\#\@_>]') {
                $replaceLen = $p.FlagLen + $p.Indent.Length + 1
                $replacement = $p.Indent
            }
            $issues.Add((New-Issue $FilePath `
                $a.Extent.StartLineNumber $a.Extent.StartColumnNumber `
                'write-ap-to-apl' 'Strip legacy flag prefix (`Write-APL` re-applies it automatically)' `
                $openQuote $replaceLen $replacement))
        }
    }

    # --- Rule: redundant n/x/s flags on Write-APL args ---------------------
    # Write-APL's internal regex at `Modules.ps1:4539` strips `n?x?n?` from
    # every chunk before processing. So any user-written flag prefix on a
    # Write-APL arg is dead text. Strip it. Only matches when the flags are
    # followed by a sign char -- otherwise those letters are real body text.
    foreach ($c in $commands) {
        if (!$c.CommandElements -or $c.CommandElements[0].Value -ne 'Write-APL') {continue}
        for ($k = 1; $k -lt $c.CommandElements.Count; $k++) {
            $el = $c.CommandElements[$k]
            if ($el -is [CommandParameterAst]) {continue}
            foreach ($a in (& $flattenArgs @($el))) {
                $isStr = ($a -is [StringConstantExpressionAst]) -or
                         ($a -is [ExpandableStringExpressionAst])
                if (!$isStr -or $a.Extent.Text.StartsWith('@')) {continue}
                $lit = & $getLiteralHead $a
                if ($lit -notmatch $wapStripRgx) {continue}
                $flagRun = $Matches[1]
                if (!$flagRun) {continue}
                $issues.Add((New-Issue $FilePath `
                    $a.Extent.StartLineNumber $a.Extent.StartColumnNumber `
                    'write-apl-redundant-flags' 'Remove `n`/`x`/`s` flag prefix -- `Write-APL` strips these internally' `
                    ($a.Extent.StartOffset + 1) $flagRun.Length ''))
            }
        }
    }

    # --- Rule: Write-Host -> Write-AP / Write-APL (OPTIONAL + WarnOnly) -----
    # AP Console prefers `Write-APL` (line) / `Write-AP` (no newline) with sign
    # prefixes (`+` green, `-` red, `!` yellow, `*` blue, `#` dim) over raw
    # `Write-Host`. The call-site rewrite depends on `-NoNewline`, foreground
    # color, and other flags, so this is warn-only -- no auto-fix even under
    # -Fix -AllOptional. The warning still surfaces so you can spot + convert
    # call-by-call.
    foreach ($c in $commands) {
        if (!$c.CommandElements) {continue}
        $nameEl = $c.CommandElements[0]
        if ($nameEl -isnot [StringConstantExpressionAst]) {continue}
        if ($nameEl.Value -ne 'Write-Host') {continue}
        $issues.Add((New-Issue $FilePath `
            $nameEl.Extent.StartLineNumber $nameEl.Extent.StartColumnNumber `
            'write-host' 'Prefer `Write-APL` / `Write-AP` with sign prefixes (`+`/`-`/`!`/`*`/`#`) over `Write-Host`' `
            $nameEl.Extent.StartOffset ($nameEl.Extent.EndOffset - $nameEl.Extent.StartOffset) 'Write-APL' `
            -Optional -WarnOnly))
    }

    # --- Rule: collapse single-statement multi-line control-flow bodies ----
    # `if/while/for/foreach/do/try/catch/finally/switch (...) {\n    <stmt>\n}`
    # becomes `... {<stmt>}` when the body qualifies. Gated by a 120-char cap so
    # we don't produce absurdly long lines.
    #
    # A body qualifies only when all of:
    #   - spans multiple lines
    #   - contains exactly one statement, which is itself on one line
    #   - contains no nested StatementBlockAst / ScriptBlockExpressionAst
    #     (no inner control flow, no `| % {...}` style scriptblock args)
    #
    # Comment handling:
    #   - comments inside the body are treated as meaningful; they move UP above
    #     the control-flow statement when the body is the parent's ONLY body
    #     (single-clause `if` with no else, any loop, bare `try` with no catch)
    #   - for multi-body parents (if/elseif/else, try/catch/finally, switch),
    #     moving a clause's comment above the parent loses context, so we skip
    #     collapse for that specific body instead
    function Get-ControlFlowBodies {
        param($rootAst)
        $out = [List[object]]::new()
        $rootAst.FindAll({$true}, $true) | % {
            $n = $_
            switch ($n.GetType().Name) {
                'IfStatementAst' {
                    $isSole = ($n.Clauses.Count -eq 1) -and ($null -eq $n.ElseClause)
                    foreach ($c in $n.Clauses) {$out.Add(@{Body = $c.Item2; Parent = $n; IsSole = $isSole})}
                    if ($n.ElseClause) {$out.Add(@{Body = $n.ElseClause; Parent = $n; IsSole = $false})}
                }
                'WhileStatementAst'   {$out.Add(@{Body = $n.Body; Parent = $n; IsSole = $true})}
                'DoWhileStatementAst' {$out.Add(@{Body = $n.Body; Parent = $n; IsSole = $true})}
                'DoUntilStatementAst' {$out.Add(@{Body = $n.Body; Parent = $n; IsSole = $true})}
                'ForStatementAst'     {$out.Add(@{Body = $n.Body; Parent = $n; IsSole = $true})}
                'ForEachStatementAst' {$out.Add(@{Body = $n.Body; Parent = $n; IsSole = $true})}
                'TryStatementAst' {
                    $isSole = ($n.CatchClauses.Count -eq 0) -and ($null -eq $n.Finally)
                    $out.Add(@{Body = $n.Body; Parent = $n; IsSole = $isSole})
                    foreach ($c in $n.CatchClauses) {$out.Add(@{Body = $c.Body; Parent = $n; IsSole = $false})}
                    if ($n.Finally) {$out.Add(@{Body = $n.Finally; Parent = $n; IsSole = $false})}
                }
                'SwitchStatementAst' {
                    foreach ($c in $n.Clauses) {$out.Add(@{Body = $c.Item2; Parent = $n; IsSole = $false})}
                    if ($n.Default) {$out.Add(@{Body = $n.Default; Parent = $n; IsSole = ($n.Clauses.Count -eq 0)})}
                }
            }
        }
        return $out
    }
    foreach ($b in (Get-ControlFlowBodies $ast)) {
        $body = $b.Body; $parent = $b.Parent
        if ($body.Extent.StartLineNumber -eq $body.Extent.EndLineNumber) {continue}
        if ($body.Statements.Count -ne 1) {continue}
        $stmt = $body.Statements[0]
        if ($stmt.Extent.StartLineNumber -ne $stmt.Extent.EndLineNumber) {continue}
        $nested = $stmt.FindAll({
            $a = $args[0]
            ($a -is [StatementBlockAst]) -or
            ($a -is [ScriptBlockExpressionAst])
        }, $true)
        if ($nested) {continue}

        # Extract comments that live inside the body.
        $bodyComments = $tokens | ? {
            "$($_.Kind)" -eq 'Comment' -and
            $_.Extent.StartOffset -gt $body.Extent.StartOffset -and
            $_.Extent.EndOffset -lt $body.Extent.EndOffset
        }
        if ($bodyComments -and !$b.IsSole) {continue}  # multi-body parent + comments ? ambiguous, skip

        # 120-char post-collapse line length check. Reconstruct what the final line
        # would look like: leading indent through body start + `{<stmt>}` + trailing
        # content through next newline (catches e.g. `} else {...}` still on the line).
        $lineStart = $text.LastIndexOf("`n", $body.Extent.StartOffset - 1)
        $lineStart = if ($lineStart -lt 0) {0} else {$lineStart + 1}
        $prefix = $text.Substring($lineStart, $body.Extent.StartOffset - $lineStart)
        $trailEnd = $text.IndexOf("`n", $body.Extent.EndOffset)
        if ($trailEnd -lt 0) {$trailEnd = $text.Length}
        $suffix = $text.Substring($body.Extent.EndOffset, $trailEnd - $body.Extent.EndOffset)
        $collapsedBody = "{$($stmt.Extent.Text)}"
        if (($prefix + $collapsedBody + $suffix).Length -gt 120) {continue}

        # Issue 1: replace body extent with tight-collapsed form.
        $issues.Add((New-Issue $FilePath `
            $body.Extent.StartLineNumber $body.Extent.StartColumnNumber `
            'collapse-block' 'Collapse single-statement block to one line' `
            $body.Extent.StartOffset ($body.Extent.EndOffset - $body.Extent.StartOffset) $collapsedBody))

        # Issue 2 (if comments): prepend them above the parent control-flow statement,
        # indented to match. Applied at lower offset so it fires AFTER the body replace
        # (descending-offset order). Body-replace wipes the comments from inside; this
        # re-inserts them above.
        if ($bodyComments) {
            $parentLineStart = $text.LastIndexOf("`n", $parent.Extent.StartOffset - 1)
            $parentLineStart = if ($parentLineStart -lt 0) {0} else {$parentLineStart + 1}
            $parentIndent = $text.Substring($parentLineStart, $parent.Extent.StartOffset - $parentLineStart)
            # Only the leading whitespace of the parent line counts as indent.
            if ($parentIndent -match '^(\s*)') {$parentIndent = $Matches[1]}
            $commentBlock = ($bodyComments | % {$parentIndent + $_.Text.TrimEnd()}) -join "`n"
            $issues.Add((New-Issue $FilePath `
                $parent.Extent.StartLineNumber 1 `
                'collapse-block' 'Move body comment above collapsed statement' `
                $parent.Extent.StartOffset 0 "$commentBlock`n$parentIndent"))
        }
    }

    # --- Rule: exactly one space between keyword/alias and its opener -------
    # Catches `if(`, `while(`, `foreach(`, `%{`, `?{`, `try{`, `else{`, `catch{`, etc.
    # Also normalizes multi-space forms like `if  (` back to a single space.
    # Only inline (same line) ? multi-line style is a different discussion.
    #
    # Tokenization notes:
    #   `%` ? Rem kind      (always, even when it's really ForEach-Object)
    #   `?` ? Generic kind  (when used as Where-Object alias)
    #   control-flow keywords have their own kinds (If, Else, Catch, ...)
    # Any `catch` / `try` / `else` / `do` can open directly with `{`, while
    # `if` / `while` / `for` / `foreach` / `switch` need `(`, and `catch` can
    # take either. So we just look at whatever opener actually follows.
    $kwKinds   = 'If','ElseIf','While','For','Foreach','Switch','Catch','Else','Try','Finally','Do'
    $aliasRem  = @{Text='%'; Kind='Rem'}       # ForEach-Object alias
    $aliasWhere = @{Text='?'; Kind='Generic'}  # Where-Object alias
    for ($i = 0; $i -lt $tokens.Count - 1; $i++) {
        $t = $tokens[$i]
        $kindStr = "$($t.Kind)"
        $isCandidate =
            ($kindStr -in $kwKinds) -or
            ($kindStr -eq $aliasRem.Kind   -and $t.Text -eq $aliasRem.Text) -or
            ($kindStr -eq $aliasWhere.Kind -and $t.Text -eq $aliasWhere.Text)
        if (!$isCandidate) {continue}
        # Skip newlines/comments when looking for the next meaningful token.
        $j = $i + 1
        while ($j -lt $tokens.Count -and "$($tokens[$j].Kind)" -in 'NewLine','Comment','LineContinuation') {$j++}
        if ($j -ge $tokens.Count) {continue}
        $next = $tokens[$j]
        $nextKind = "$($next.Kind)"
        if ($nextKind -notin 'LParen','LCurly') {continue}
        if ($t.Extent.EndLineNumber -ne $next.Extent.StartLineNumber) {continue}
        $gap = $next.Extent.StartOffset - $t.Extent.EndOffset
        if ($gap -eq 1) {continue}
        $sym = if ($nextKind -eq 'LParen') {'('} else {'{'}
        $issues.Add((New-Issue $FilePath `
            $t.Extent.EndLineNumber $t.Extent.EndColumnNumber `
            'spacing-keyword' ("Use exactly one space between ``$($t.Text)`` and ``$sym``") `
            $t.Extent.EndOffset $gap ' '))
    }

    # --- Rule: pwsh-7 native ternary ? AP Console `?:` polyfill (OPTIONAL) ---
    # `cond ? a : b` only parses in PowerShell 7+. AP Console's `?:` (Invoke-Ternary)
    # works in BOTH Windows PowerShell 5.1 and PS Core, so scripts that need to run
    # in either should use `?:`. Always warn; only fix when `-Fix -AllOptional`.
    #
    # Mapping: `<cond> ? <a> : <b>` ? `?: <cond> <a'> <b'>` where each branch stays
    # bare if it's a literal constant or variable (no side effects, no lazy-eval
    # benefit) and otherwise gets wrapped in `{...}`. `?:` auto-invokes scriptblock
    # args, which preserves the short-circuit semantics native ternary has.
    #
    # Type checks use `.GetType().Name -eq ...` instead of `-is [FullTypeName]`
    # so the linter itself remains parseable/runnable on Windows PowerShell 5.1,
    # where `TernaryExpressionAst` simply doesn't exist as a type. On 5.1, the
    # FindAll scan just returns zero matches (and any file that actually contains
    # ternary syntax wouldn't parse on 5.1 anyway ? we'd bail at ParseInput).
    $wrap = {
        param($x)
        $kind = $x.GetType().Name
        $simple = $kind -eq 'ConstantExpressionAst' -or
                  $kind -eq 'StringConstantExpressionAst' -or
                  $kind -eq 'VariableExpressionAst'
        if ($simple) {$x.Extent.Text} else {"{$($x.Extent.Text)}"}
    }
    $ternaries = $ast.FindAll({$args[0].GetType().Name -eq 'TernaryExpressionAst'}, $true)
    foreach ($te in $ternaries) {
        $cond = $te.Condition.Extent.Text
        $aTxt = & $wrap $te.IfTrue
        $bTxt = & $wrap $te.IfFalse
        $replacement = "?: $cond $aTxt $bTxt"
        $issues.Add((New-Issue $FilePath `
            $te.Extent.StartLineNumber $te.Extent.StartColumnNumber `
            'use-apc-ternary' "Prefer AP Console ``?:`` over pwsh-7 native ternary for cross-version scripts" `
            $te.Extent.StartOffset ($te.Extent.EndOffset - $te.Extent.StartOffset) $replacement `
            -Optional))
    }

    # --- Post-filter: drop issues inside auto-generated AP-Compile blocks ---
    # Those blocks use their own injection-template style (e.g. `if(` / `else{`)
    # and regenerate on every recompile, so linting them produces churn that the
    # next compile just undoes. Treat the fenced region as opaque.
    $cStart = $text.IndexOf('=======================================START=OF=COMPILER')
    $cEnd = $text.IndexOf('========================================END=OF=COMPILER')
    if ($cStart -ge 0 -and $cEnd -gt $cStart) {
        return @($issues | ? {$_.Offset -lt $cStart -or $_.Offset -gt $cEnd})
    }
    return $issues.ToArray()
}

function Apply-Fixes {
    param([string]$FilePath, [object[]]$Issues, [switch]$IncludeOptional)
    $text = [System.IO.File]::ReadAllText($FilePath)
    # Optional fixes (e.g. native-ternary -> `?:`) only land when -AllOptional was
    # passed; normal -Fix leaves them as warnings for the user to review.
    # WarnOnly issues (e.g. Write-Host) are never auto-fixed regardless of flags --
    # the call-site rewrite is too context-dependent to be safe.
    # Apply highest-offset fixes first so earlier offsets stay valid.
    $sorted = $Issues | ? {!$_.WarnOnly -and ($IncludeOptional -or !$_.Optional)} | sort Offset -Descending
    foreach ($i in $sorted) {
        $text = $text.Substring(0, $i.Offset) + $i.Replacement + $text.Substring($i.Offset + $i.Length)
    }
    [System.IO.File]::WriteAllText($FilePath, $text)
    return @($sorted).Count
}

# Colorize a single line of PowerShell source using PSReadLine's configured palette
# when available. Falls back to plain text if PSReadLine isn't loaded or tokenization
# fails. Uses PSParser (legacy tokenizer, still ships with PS Core) because its
# PSTokenType enum maps cleanly to the PSReadLineOption color properties.
function Render-ColoredLine {
    param([string]$Line)
    $opt = Get-PSReadLineOption -ea 0
    if (!$opt -or !$Line) {return $Line}
    $toks = $null
    try {$toks = [PSParser]::Tokenize($Line, [ref]$null)} catch {return $Line}
    if (!$toks) {return $Line}
    $reset = "$([char]0x1b)[0m"
    $map = @{
        Keyword          = $opt.KeywordColor
        Command          = $opt.CommandColor
        Variable         = $opt.VariableColor
        String           = $opt.StringColor
        Number           = $opt.NumberColor
        Comment          = $opt.CommentColor
        Type             = $opt.TypeColor
        Member           = $opt.MemberColor
        Operator         = $opt.OperatorColor
        CommandParameter = $opt.ParameterColor
    }
    $out = ""; $pos = 0
    foreach ($t in $toks) {
        # Preserve any whitespace or punctuation between tokens verbatim.
        if ($t.Start -gt $pos) {$out += $Line.Substring($pos, $t.Start - $pos)}
        $color = $map["$($t.Type)"]
        # Use the source substring rather than $t.Content -- the latter strips sigils
        # (e.g. `$items` -> `items`), which shortens the rendered line and shifts the
        # caret row off by one under downstream issues.
        $txt = $Line.Substring($t.Start, $t.Length)
        if ($color) {$out += $color + $txt + $reset} else {$out += $txt}
        $pos = $t.Start + $t.Length
    }
    if ($pos -lt $Line.Length) {$out += $Line.Substring($pos)}
    return $out
}

# Print the source line an issue lives on, plus a red caret row underneath
# pointing at the exact character range ? same shape as prettier/eslint/rustc.
function Show-Callsite {
    param([string]$Text, [int]$Offset, [int]$Length)
    $lineStart = $Text.LastIndexOf("`n", [Math]::Max(0, $Offset - 1))
    $lineStart = if ($lineStart -lt 0) {0} else {$lineStart + 1}
    $lineEnd = $Text.IndexOf("`n", $Offset)
    if ($lineEnd -lt 0) {$lineEnd = $Text.Length}
    $lineText = $Text.Substring($lineStart, $lineEnd - $lineStart).TrimEnd("`r")
    $col = $Offset - $lineStart
    $caretLen = [Math]::Max(1, [Math]::Min($Length, $lineText.Length - $col))
    $esc = [char]0x1b
    $dim = "$esc[90m"; $red = "$esc[91;1m"; $reset = "$esc[0m"
    $colored = Render-ColoredLine $lineText
    Write-APL -NS "        $dim|$reset  $colored"
    Write-APL -NS "        $dim|$reset  $(' ' * $col)$red$('^' * $caretLen)$reset"
}

function Show-Issues {
    param([object[]]$Issues, [switch]$Verbose)
    foreach ($g in ($Issues | group File)) {
        Write-APL -NS ""
        Write-APL -NS "*$($g.Name)"
        $fileText = if ($Verbose) {[System.IO.File]::ReadAllText($g.Name)} else {$null}
        $g.Group | sort Line, Col | % {
            $loc = "{0,4}:{1,-3}" -f $_.Line, $_.Col
            # Suffix: `*` = optional (opt-in fix), `~` = warn-only (never auto-fixed).
            $suffix = if ($_.WarnOnly) {'~'} elseif ($_.Optional) {'*'} else {''}
            $ruleLabel = "$($_.Rule)$suffix"
            Write-APL -NS "#  $loc  ","!$("{0,-20}" -f $ruleLabel)"," ","#$($_.Message)"
            if ($Verbose -and $fileText) {Show-Callsite $fileText $_.Offset $_.Length}
        }
    }
}

# --- Main ---------------------------------------------------------------
$files = [List[string]]::new()
foreach ($p in $Path) {
    # Normalize path across OS/runtime combos (WSL caller ? Windows pwsh etc.)
    $p = Convert-PathFormat $p -To CurrOS -AssumeWSL
    if (Test-Path $p -PathType Container) {
        Get-ChildItem -Path $p -File -Recurse -Include *.ps1,*.psm1 -ea 0 | % {$files.Add($_.FullName)}
    } elseif (Test-Path $p) {
        Get-Item -Path $p -ea 0 | % {$files.Add($_.FullName)}
    } else {
        Get-ChildItem -Path $p -File -ea 0 | % {$files.Add($_.FullName)}
    }
}
$files = $files | sort -Unique

if (!$files) {
    Write-APL "!","No files matched: $($Path -join ', ')"
    exit 0
}

$allIssues = [List[object]]::new()
foreach ($f in $files) {
    foreach ($issue in (Find-Issues $f)) {$allIssues.Add($issue)}
}

if (!$allIssues) {
    if (!$Quiet) {Write-APL "+","$([char]0x2713) No style issues across $($files.Count) file(s)."}
    exit 0
}

$fileCount = @($allIssues | group File).Count

if ($Fix) {
    $fixed = 0
    foreach ($g in ($allIssues | group File)) {$fixed += Apply-Fixes $g.Name $g.Group -IncludeOptional:$AllOptional}
    $warnOnly = @($allIssues | ? {$_.WarnOnly}).Count
    $skippedOptional = $allIssues.Count - $fixed - $warnOnly
    Write-APL "+","$([char]0x2713) Fixed $fixed issue(s) across $fileCount file(s)."
    if ($skippedOptional -gt 0) {
        Write-APL -NS "#  $skippedOptional issue(s) marked optional. Re-run with ","*-Fix -AllOptional","# to apply those too."
    }
    if ($warnOnly -gt 0) {
        Write-APL -NS "#  $warnOnly issue(s) marked warn-only (~). These need manual refactoring; no auto-fix is safe."
    }
    exit 0
}

if (!$Quiet) {Show-Issues $allIssues -Verbose:($VerbosePreference -ne 'SilentlyContinue')}

$optCount = @($allIssues | ? {$_.Optional -and !$_.WarnOnly}).Count
$warnCount = @($allIssues | ? {$_.WarnOnly}).Count
Write-APL -NS ""
Write-APL "!","Found $($allIssues.Count) issue(s) across $fileCount file(s)."
$tail = if ($optCount -gt 0) {" (add ","*-AllOptional"," to also fix the $optCount rule(s) marked *)"} else {@()}
$warnTail = if ($warnCount -gt 0) {"; $warnCount marked warn-only (~) need manual refactoring"} else {""}
Write-APL -NS (@("Re-run with ","*-Fix"," to apply") + $tail + @("$warnTail."))
exit $allIssues.Count




